{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    for key in ("nodes", "core_distance", "distances"):
        if key not in case:
            raise ValueError("missing required field: " + key)

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list):
        raise ValueError("nodes must be a list")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be an object")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    seen_nodes = set()
    node_list = []
    for node in nodes:
        if not isinstance(node, str):
            raise ValueError("node identifiers must be strings")
        if node in seen_nodes:
            raise ValueError("duplicate node identifier")
        seen_nodes.add(node)
        node_list.append(node)

    for node in node_list:
        if node not in core_distance:
            raise ValueError("missing core distance")
        if not is_number(core_distance[node]):
            raise ValueError("core distances must be finite numbers")

    allowed_core_keys = set(core_distance.keys())
    if allowed_core_keys != seen_nodes:
        raise ValueError("core_distance keys must match nodes")

    edges = []
    seen_pairs = set()
    for index, item in enumerate(distances):
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError("distance entries must be triples")
        left, right, distance = item
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("distance endpoints must be strings")
        if left not in seen_nodes or right not in seen_nodes:
            raise ValueError("distance endpoint not present in nodes")
        if left == right:
            raise ValueError("self distances are not MST edges")
        if not is_number(distance):
            raise ValueError("distances must be finite numbers")

        a, b = (left, right) if left <= right else (right, left)
        pair = (a, b)
        if pair in seen_pairs:
            raise ValueError("duplicate undirected distance pair")
        seen_pairs.add(pair)

        weight = max(float(core_distance[left]), float(core_distance[right]), float(distance))
        edges.append((weight, a, b, index))

    parent = {node: node for node in node_list}
    rank = {node: 0 for node in node_list}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            return False
        if rank[root_left] < rank[root_right]:
            parent[root_left] = root_right
        elif rank[root_left] > rank[root_right]:
            parent[root_right] = root_left
        else:
            parent[root_right] = root_left
            rank[root_left] += 1
        return True

    selected = []
    for weight, left, right, index in sorted(edges, key=lambda e: (e[0], e[1], e[2], e[3])):
        if union(left, right):
            selected.append([left, right, weight])
            if len(selected) == max(0, len(node_list) - 1):
                break

    if len(selected) != max(0, len(node_list) - 1):
        raise ValueError("distance graph is disconnected")

    total_weight = sum(edge[2] for edge in selected)
    return {"mst_edges": selected, "total_weight": total_weight}
